/* ---------- typed model ---------- */
type Bag = Record<string, unknown>;
type Dict = Record<string, string>;
export type PlCal = { id: string; kind: string; ref?: string; on: boolean; color: string; name?: string };
export type PlWait = { id: string; pid: string; svc: string; pr: string; from: string; to: string; tod: string; prio: string; note: string; status: string; created: string; by: string; offer: { start: string; end: string; pr: string; room: string | null; est: string | null; from?: string } | null; hist: { at: string; act: string; by?: string; appt?: string }[]; appt?: string; min?: number };
