export type PlState = { v: number; synthetic: boolean; rev: number; prefs: PlPrefs; colors: Dict; cals: PlCal[]; wait: PlWait[]; audit: { id: string; ts: string; role: string; user: string; act: string; ref: string; detail: string }[]; [k: string]: unknown };
/** A non-appointment block in a day column: internal event, maintenance, external busy time. */
type PlBlk = { id: string; kind: string; title: string; start: number; end: number; prs: string[]; ids?: string[]; room: string | null; grp?: string | null; src?: string };
type PlLane = { a?: ClAppt; b?: PlBlk; s: number; e: number; lane?: number; lanes?: number };
