type PlUi = { view: string; mode: string; date: string | null; flt: PlFlt; q: string; drawer: string | null; panel: string | null; sel: string | null; anim: number; flash?: string | null; keepScroll?: boolean; lr?: string; mini?: string | null; qc?: { x: number; y: number; col: HTMLElement } | null; right?: boolean; rp?: string; stale?: boolean; upOpen?: boolean; wf?: string; wopen?: string | null; [k: string]: unknown };
type PlChk = { start: string; end: string; pr: string; est: string; room: string | null; cs: ClConf[] };
type PlNp = { pid: string; q: string; svc: string; pr: string; tod: string; from: string; mode: string; date: string; time: string; sel: number | null; notes: string; idem: string; days: number; sugg?: (ClSlot & { score: number; why: string[] })[]; chk?: PlChk | null };
type PlApp = { st: PlState | null; ui: PlUi; np?: PlNp };
type DlgOpts = { wide?: boolean; xl?: boolean; icon?: string; foot?: string; cancel?: boolean; cancelLabel?: string; ok?: boolean; okLabel?: string; danger?: boolean; onOk?: (m: HTMLElementX) => boolean | void; mount?: (m: HTMLElementX) => void };
