/* ===== v67 · Calendar & Planning — a second, planning-oriented workspace over the Gestion Calendrier domain.
   It owns only presentation preferences, the waiting list and its matching, and calendar visibility sets.
   Appointments, availability, rooms, statuses: Gestion Calendrier (domain API, same roles). Visit stages & tasks: Gestion Cabinet. Identity: Patients. ===== */
const PL_KEY="remotion-planning";
const PL: PlApp={st:null,ui:{view:"cal",mode:"week",date:null,flt:{pr:"",est:"",svc:"",st:""},q:"",drawer:null,panel:null,sel:null,anim:0}};
class PlErr extends Error{k: string;x: unknown;constructor(k: string,x?: unknown){super(k);this.k=k;this.x=x}}
const plId=(p: string)=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const plNow=()=>clNow();const plToday=()=>clToday(CL_ORG_TZ);
const PL_PAL=["#22a565","#3b82f6","#8b5cf6","#e5487a","#f59e0b","#14b8a6","#6366f1","#ef4444","#0ea5e9","#a855f7","#64748b"];
const PL_SVC_DEF: Dict={sv1:"#22a565",sv2:"#8b5cf6",sv3:"#e5487a",sv4:"#14b8a6",sv5:"#a855f7",sv6:"#6366f1",sv7:"#0ea5e9",sv8:"#f59e0b",sv9:"#3b82f6"};
const PL_STC: Dict={pending:"#f59e0b",requested:"#f59e0b",draft:"#94a3b8",confirmed:"#22a565",checkedin:"#3b82f6",inprogress:"#8b5cf6",completed:"#64748b",cancelled:"#ef4444",noshow:"#ef4444"};

/* ---------- store (planning-owned data only) ---------- */
function plSt(): PlState{if(PL.st)return PL.st;let s: PlState | null=null;try{s=JSON.parse(localStorage.getItem(PL_KEY)||"null")}catch(e){}if(!s||s.v!==1||!Array.isArray(s.wait))s=plSeed();PL.st=s;return s}
function plSave(){const S=PL.st;S!.rev=(S!.rev||0)+1;try{localStorage.setItem(PL_KEY,JSON.stringify(S))}catch(e){console.warn("pl save",e)}}
function plReload(){try{const s=JSON.parse(localStorage.getItem(PL_KEY)||"null");if(s&&s.v===1&&PL.st&&(s.rev||0)>(PL.st.rev||0)){Object.keys(PL.st).forEach(k=>delete PL.st![k]);Object.assign(PL.st,s)}}catch(e){}return PL.st}
function plLog(act: string,ref?: string | null,detail?: unknown){const S=plSt();S.audit.unshift({id:plId("a"),ts:new Date().toISOString(),role:clRole(),user:clUser(),act,ref:ref||"",detail:String(detail||"").slice(0,160)});if(S.audit.length>400)S.audit.length=400}
function plSeed(): PlState{clSt();const T=clDateOf(Date.now(),CL_ORG_TZ);const S: PlState={v:1,synthetic:true,rev:1,prefs:{mode:"week",colorBy:"type",weekend:"auto",hourH:88,dayStart:"07:00",dayEnd:"20:00"},colors:{},
   cals:[{id:"me",kind:"me",on:true,color:"#22a565"},...["pr1","pr5"].map((p,i)=>({id:"c-"+p,kind:"pr",ref:p,on:true,color:["#3b82f6","#8b5cf6"][i]})),{id:"c-r2",kind:"room",ref:"r2",on:true,color:"#f59e0b"},{id:"c-r3",kind:"room",ref:"r3",on:true,color:"#e5487a"},{id:"c-team",kind:"team",on:true,color:"#14b8a6"}],
   wait:[],audit:[]};PL.st=S;
  const W=(pid: string,svc: string,pr: string,days: number,tod: string,prio: string,note: string,o: Partial<PlWait>={})=>S.wait.push(Object.assign({id:plId("w"),pid,svc,pr:pr||"",from:T,to:clAddD(T,days),tod,prio,note,status:"waiting",created:new Date(Date.now()-(days*3600e3)).toISOString(),by:"Accueil (démo)",offer:null,hist:[]},o));
  W("pa3","sv1","pr1",14,"am","high","Souhaite avancer sa séance (douleurs) — démonstration");W("pa7","sv3","",7,"any","normal","Disponible sur appel, 30 min de trajet");W("pa11","sv6","pr6",21,"pm","normal","Après 15 h uniquement (travail)");W("pa5","sv4","",30,"any","low","Liste d’attente bilan — démonstration",{status:"booked",hist:[{at:new Date(Date.now()-864e5).toISOString(),act:"booked"}]});
  return S}

/* ---------- presentation helpers ---------- */
const plHash=(s: unknown)=>{let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))|0;return Math.abs(h)};
function plSvcColor(svc: string){return plSt().colors[svc]||PL_SVC_DEF[svc]||PL_PAL[plHash(svc)%PL_PAL.length]}
function plColor(a: ClAppt){const by=plSt().prefs.colorBy;if(by==="pr")return clPrColor(a.pr);if(by==="status")return PL_STC[a.status]||"#64748b";return plSvcColor(a.svc)}
const plInitials=(n: string | null | undefined)=>String(n||"?").split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase();
const plAvColor=(n: string)=>PL_PAL[plHash(n)%PL_PAL.length];
const plCanSee=(a: ClAppt)=>clCanSeeDetails(a);
const plName=(a: ClAppt)=>plCanSee(a)?clWho(a,true).replace(/ \((externe|external|extern|خارجي)\)$/,""):L4("Occupé|Busy|Belegt|مشغول");
const plWeekStart=(d: string)=>{let s=d;while(clWd(s)!==1)s=clAddD(s,-1);return s};

/* ---------- calendar visibility ("My calendars") ---------- */
function plCalOf(kind: string,ref?: string | null){return plSt().cals.find(c=>c.kind===kind&&(kind==="me"||c.ref===ref))}
function plVisible(a: ClAppt){const f=PL.ui.flt;if(f.pr&&a.pr!==f.pr)return false;if(f.est&&a.est!==f.est)return false;if(f.svc&&a.svc!==f.svc)return false;
  if(f.st){if(f.st==="cancelled"?a.status!=="cancelled"&&a.status!=="noshow":a.status!==f.st)return false}else if(!CL_ACTIVE(a.status))return false;
  const me=a.pr===clMe()?plCalOf("me"):null;const pc=plCalOf("pr",a.pr);const rc=a.room?plCalOf("room",a.room):null;
  if(me&&!me.on&&!(pc&&pc.on))return false;if(pc&&!pc.on&&!(me&&me.on))return false;if(rc&&!rc.on)return false;
  const q=PL.ui.q.trim().toLowerCase();if(q){const hay=(plName(a)+" "+clSvcName(a.svc)+" "+rmPracName(a.pr)+" "+(a.room?clRes(a.room)?.n||"":"")).toLowerCase();if(!hay.includes(q))return false}return true}
function plItems(from: number,to: number){clSt();return clItems(from,to).filter(plVisible).sort((a,b)=>a.start<b.start?-1:a.start>b.start?1:0)}
/* non-appointment occupancy of a day: internal events (team meetings / blocked time) recorded as availability exceptions, room maintenance, external busy, HR leave */
function plBlocks(date: string){const S=clSt();const tz=CL_ORG_TZ;const out: PlBlk[]=[];const team=plCalOf("team");const grp: Record<string, PlBlk>={};const f=PL.ui.flt;
  S.exc.filter(x=>clT(x)&&x.from<=date&&x.to>=date&&x.start&&x.end&&x.pr!=="*").forEach(x=>{if(f.pr&&x.pr!==f.pr)return;const k=x.grp||x.id;if(grp[k]){grp[k].prs.push(x.pr);grp[k].ids!.push(x.id);return}const it={id:"x:"+k,kind:x.evt==="meeting"?"meeting":"block",title:x.reason||L4(CL_EXK[x.kind]||""),start:clZms(date,x.start!,tz),end:clZms(date,x.end!,tz),prs:[x.pr],ids:[x.id],room:x.room||null,grp:x.grp||null,src:x.src||"cal"};grp[k]=it;out.push(it)});
  S.res.filter(r=>clT(r)).forEach(r=>(r.maint||[]).filter(m=>m.from<=date&&m.to>=date&&m.start&&m.end&&m.src!=="planning").forEach(m=>{if(f.est&&r.est!==f.est)return;const rc=plCalOf("room",r.id);if(rc&&!rc.on)return;out.push({id:"m:"+m.id,kind:"maint",title:m.reason||L4(CL_EXK.maint),start:clZms(date,m.start,tz),end:clZms(date,m.end,tz),room:r.id,prs:[]})}));
  (S.ext||[]).filter(e=>clT(e)&&clDateOf(Date.parse(e.start),tz)===date).forEach(e=>{if(f.pr&&e.pr!==f.pr)return;out.push({id:"e:"+e.id,kind:"ext",title:e.title,start:Date.parse(e.start),end:Date.parse(e.end),prs:[e.pr],room:null})});
  return out.filter(b=>b.kind!=="meeting"||!team||team.on)}
function plAllDay(date: string){const S=clSt();const out: { kind: string; title: string; pr?: string }[]=[];rmPracs().forEach(p=>{if(PL.ui.flt.pr&&p.id!==PL.ui.flt.pr)return;clHrLeaves(p.id).filter(l=>l.from<=date&&l.to>=date).forEach(l=>out.push({kind:"leave",title:rmPracName(p)+" — "+L4("congé|leave|Urlaub|إجازة"),pr:p.id}));S.exc.filter(x=>clT(x)&&x.pr===p.id&&!x.start&&x.from<=date&&x.to>=date).forEach(x=>out.push({kind:"leave",title:rmPracName(p)+" — "+(x.reason||L4(CL_EXK[x.kind])),pr:p.id}))});
  S.exc.filter(x=>clT(x)&&x.pr==="*"&&x.from<=date&&x.to>=date).forEach(x=>out.push({kind:"closure",title:(x.reason||L4(CL_EXK[x.kind]))+(x.est?" · "+rmEstName(x.est):"")}));
  S.res.filter(r=>clT(r)).forEach(r=>(r.maint||[]).filter(m=>m.from<=date&&m.to>=date&&!m.start).forEach(m=>out.push({kind:"maint",title:r.n+" — "+(m.reason||L4(CL_EXK.maint))})));return out}
/* side-by-side layout of overlapping events in a column */
function plLayout(evs: PlLane[]){const s=evs.slice().sort((a,b)=>a.s-b.s||b.e-a.e);let group: PlLane[]=[],end=-1;const out: PlLane[]=[];const flush=()=>{const lanes: number[]=[];group.forEach(ev=>{let i=lanes.findIndex(t=>t<=ev.s);if(i<0){i=lanes.length;lanes.push(0)}lanes[i]=ev.e;ev.lane=i});group.forEach(ev=>ev.lanes=lanes.length);out.push(...group);group=[]};
  s.forEach(ev=>{if(ev.s>=end&&group.length)flush();group.push(ev);end=Math.max(end,ev.e)});if(group.length)flush();return out}

/* ---------- smart slot suggestions: ranks the calendar's own free slots (never invents availability) ---------- */
function plUsualPr(pid: string | null | undefined){if(!pid)return null;const now=plNow();const c: Record<string, number>={};clItems(now-365*864e5,now).filter(a=>a.pid===pid&&a.status==="completed").forEach(a=>c[a.pr]=(c[a.pr]||0)+1);const e=Object.entries(c).sort((a,b)=>b[1]-a[1])[0];return e?{pr:e[0],n:e[1]}:null}
function plSuggest(o: { svc: string; pr?: string; pid?: string | null; tod?: string; from?: string; days?: number; est?: string; limit?: number }){const svc=clSvc(o.svc);if(!svc)return [];const prs=o.pr?[o.pr]:(svc.pracs?.length?svc.pracs:rmPracs().map(p=>p.id)).filter(p=>rmPrac(p)?.active!==false);const from=o.from&&o.from>plToday()?o.from:plToday();
  const slots=clSlots({svc:o.svc,prs,from,days:o.days||14,limit:220,pid:o.pid,est:o.est||undefined});if(!slots.length)return [];const usual=plUsualPr(o.pid);const p=o.pid&&typeof paFind==="function"?paFind(o.pid):null;const t0=Date.parse(slots[0].start);
  const busy: Record<string, ClAppt[]>={};const near=(s: ClSlot)=>{const k=s.pr+clDateOf(Date.parse(s.start),CL_ORG_TZ);if(!busy[k]){const d=clDateOf(Date.parse(s.start),CL_ORG_TZ);busy[k]=clItems(clZms(d,"00:00",CL_ORG_TZ),clZms(clAddD(d,1),"00:00",CL_ORG_TZ),{active:true}).filter(a=>a.pr===s.pr)}const st=Date.parse(s.start),en=Date.parse(s.end);return busy[k].some(a=>Math.abs(Date.parse(a.end)-st)<=10*60000||Math.abs(Date.parse(a.start)-en)<=10*60000)};
  const sc=slots.map(s=>{const st=Date.parse(s.start);const h=+clTimeOf(st,CL_ORG_TZ).slice(0,2);const why=[];let v=100-Math.min(60,(st-t0)/864e5*6);
    if(usual&&usual.pr===s.pr){v+=28;why.push("usual")}if(o.tod==="am"&&h<12||o.tod==="pm"&&h>=12){v+=18;why.push("tod")}else if(o.tod&&o.tod!=="any")v-=40;if(near(s)){v+=14;why.push("gap")}if(p?.admin?.est&&s.est===p.admin.est){v+=8;why.push("site")}if(st-t0<864e5)why.push("soon");return Object.assign({},s,{score:v,why})});
  const seen=new Set();return sc.sort((a,b)=>b.score-a.score||(a.start<b.start?-1:1)).filter(s=>{const k=s.start.slice(0,13)+s.pr;if(seen.has(k))return false;seen.add(k);return true}).slice(0,o.limit||6)}
const PL_WHY: Dict={usual:"Praticien habituel|Usual practitioner|Gewohnter Behandler|الممارس المعتاد",tod:"Moment préféré|Preferred time|Bevorzugte Zeit|الوقت المفضل",gap:"Comble un trou|Fills a gap|Füllt eine Lücke|يملأ فراغًا",site:"Site du patient|Patient’s site|Standort des Patienten|موقع المريض",soon:"Au plus tôt|Earliest|Frühestens|الأقرب"};

/* ---------- waiting list (owned here) with automatic matching on freed slots ---------- */
function plWaitAdd(d: Partial<PlWait>){clNeed("appt.create");if(!d.pid||!(typeof paFind==="function"&&paFind(d.pid)))throw new PlErr("pl_eInvalid",L4("patient|patient|Patient|المريض"));if(!clSvc(d.svc))throw new PlErr("pl_eInvalid",L4("type de rendez-vous|event type|Terminart|نوع الموعد"));if(!d.from||!d.to||d.to<d.from)throw new PlErr("pl_eInvalid",L4("période|period|Zeitraum|الفترة"));
  const S=plSt();if(S.wait.some(w=>w.pid===d.pid&&w.svc===d.svc&&["waiting","offered"].includes(w.status)))throw new PlErr("pl_eDupWait");const w: PlWait={id:plId("w"),pid:d.pid,svc:d.svc!,pr:d.pr||"",from:d.from,to:d.to,tod:d.tod||"any",prio:d.prio||"normal",note:String(d.note||"").slice(0,240),status:"waiting",created:new Date().toISOString(),by:clUser(),offer:null,hist:[{at:new Date().toISOString(),act:"create",by:clUser()}]};S.wait.unshift(w);plLog("wait.add",w.id,paName(paFind(d.pid)));plSave();return w}
function plWaitSet(id: string,st: string){clNeed("appt.create");const w=plSt().wait.find(x=>x.id===id);if(!w)throw new PlErr("pl_eNotFound");w.status=st;if(st==="waiting")w.offer=null;w.hist.push({at:new Date().toISOString(),act:st,by:clUser()});plLog("wait."+st,id,"");plSave();return w}
function plWaitSlots(w: PlWait,limit?: number){return plSuggest({pid:w.pid,svc:w.svc,pr:w.pr,tod:w.tod,from:w.from>plToday()?w.from:plToday(),days:Math.max(1,(Date.parse(w.to)-Date.parse(w.from>plToday()?w.from:plToday()))/864e5+1),limit:limit||3})}
function plWaitBook(id: string,slot: ClSlot,idem?: string){const S=plSt();const w=S.wait.find(x=>x.id===id);if(!w||!["waiting","offered"].includes(w.status))throw new PlErr("pl_eState");const r=clBook({pid:w.pid,svc:w.svc,pr:slot.pr,room:slot.room,est:slot.est,start:slot.start,end:slot.end,status:"confirmed",notesInt:L4("Réservé depuis la liste d’attente|Booked from the waiting list|Aus der Warteliste gebucht|حُجز من قائمة الانتظار"),idem:idem||("wl-"+id+"-"+slot.start)},{});w.status="booked";w.appt=r.item.id;w.hist.push({at:new Date().toISOString(),act:"booked",by:clUser(),appt:r.item.id});plLog("wait.booked",id,r.item.id);plSave();return r.item}
function plWaitPrio(w: PlWait){return {urgent:0,high:1,normal:2,low:3}[w.prio]??2}
/* a cancellation frees a slot: offer it to the best matching waiting-list entry (still re-validated by the calendar at booking) */
function plOnFreed(ev: RmEv){const p=ev.p as { appt: string; pr: string; start: string; end: string; room: string | null; est: string | null };const S=plSt();const st=Date.parse(p.start),en=Date.parse(p.end);if(st<plNow())return;const d=clDateOf(st,CL_ORG_TZ);const h=+clTimeOf(st,CL_ORG_TZ).slice(0,2);
  const m=S.wait.filter(w=>w.status==="waiting"&&w.from<=d&&w.to>=d&&(!w.pr||w.pr===p.pr)&&(w.tod==="any"||(w.tod==="am")===(h<12))).filter(w=>{const sv=clSvc(w.svc);return sv&&(!sv.pracs?.length||sv.pracs.includes(p.pr))&&sv.dur*60000<=en-st}).sort((a,b)=>plWaitPrio(a)-plWaitPrio(b)||(a.created<b.created?-1:1));
  for(const w of m){const sv=clSvc(w.svc);const slot={start:p.start,end:clIso(st+sv!.dur*60000),pr:p.pr,room:p.room,est:p.est};const cs=clCheck(Object.assign({svc:w.svc,pid:w.pid},slot),{staffSkipNotice:true});if(clBlocking(cs).length)continue;
   w.status="offered";w.offer=Object.assign(slot,{from:p.appt});w.hist.push({at:new Date().toISOString(),act:"offered",by:"auto"});plLog("wait.offered",w.id,p.appt);plSave();
   rmNotify("rmCal",L4("Créneau libéré — liste d’attente|Slot freed — waiting list|Termin frei — Warteliste|موعد متاح — قائمة الانتظار"),(typeof paFind==="function"?paName(paFind(w.pid)):"")+" · "+clDT(p.start,{weekday:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}),{pri:"high",open:()=>{plOpen();setTimeout(()=>plGo("wait"),400)}});return w}return null}
function plIntFreed(){rmOn("appointment.cancelled","planning",ev=>plOnFreed(ev))}

