function plEventSave(d: { kind?: string; title?: string; date?: string; start?: string; end?: string; prs?: string[]; room?: string | null }){const kind=d.kind==="meeting"?"meeting":"block";if(!String(d.title||"").trim())throw new PlErr("pl_eInvalid",L4("intitulé|title|Titel|العنوان"));if(!d.date||!d.start||!d.end||clMin(d.end)<=clMin(d.start))throw new PlErr("pl_eInvalid",L4("horaires|times|Zeiten|الأوقات"));const prs=(d.prs||[]).filter(p=>rmPrac(p));if(!prs.length)throw new PlErr("pl_eInvalid",L4("participants|attendees|Teilnehmer|المشاركون"));
  const grp=plId("g");const made: string[]=[];try{prs.forEach(pr=>{const r=clExcAdd({pr,kind:kind==="meeting"?"block":"block",from:d.date,to:d.date,start:d.start,end:d.end,reason:d.title!.trim(),grp,evt:kind,room:d.room||null,src:"planning"});made.push(r.exc.id)})}catch(e){made.forEach(id=>{try{clExcDel(id)}catch(x){}});throw e}
  if(d.room){const r=clRes(d.room);if(r){r.maint.push({id:clId("m"),ref:grp,from:d.date,to:d.date,start:d.start,end:d.end,reason:d.title!.trim(),src:"planning",at:new Date().toISOString(),by:clUser()});clSave()}}
  plLog("event.create",grp,d.title);const imp=prs.flatMap(p=>clImpacted(p,d.date,d.date));return {grp,impacted:imp}}
function plEventDelete(grpOrId: string){const S=clSt();const xs=S.exc.filter(x=>clT(x)&&(x.grp===grpOrId||x.id===grpOrId));if(!xs.length)throw new PlErr("pl_eNotFound");xs.forEach(x=>clExcDel(x.id));S.res.forEach(r=>{r.maint=(r.maint||[]).filter(m=>!(m.src==="planning"&&m.ref===grpOrId))});clSave();plLog("event.delete",grpOrId,xs[0].reason||"")}

