   if(col!==D.g!.parentElement)col!.appendChild(D.g!);const d0=clZms(col!.dataset.plcol!,P.dayStart,CL_ORG_TZ);let s,en;
   if(D.resize){s=Date.parse(D.a.start);const y=e.clientY-gr.top;en=d0+Math.round(y/HH*4)/4*36e5;en=Math.max(s+15*60000,en)}else{const y=e.clientY-gr.top-D.dy;s=d0+Math.round(y/HH*4)/4*36e5;s=Math.max(d0,s);en=s+D.dur}
