  const K=[["cal",L4("Rendez-vous|Appointments|Termine|المواعيد"),act.length,L4("hors annulés|excl. cancelled|ohne Stornos|دون الملغاة")],["chart",L4("Taux de remplissage|Fill rate|Auslastung|نسبة الإشغال"),av?Math.round(bk/av*100)+" %":"—",(bk/60).toFixed(0)+" / "+(av/60).toFixed(0)+" h"],["userX",L4("Absences|No-shows|Fehltermine|الغياب"),past.length?Math.round(ns/past.length*100)+" %":"—",ns+" / "+past.length],["x",L4("Annulations|Cancellations|Stornierungen|الإلغاءات"),cn,its.length?Math.round(cn/its.length*100)+" %":""],["clock",L4("Délai moyen de prise de RDV|Average booking lead time|Ø Vorlaufzeit|متوسط مهلة الحجز"),lead.length?(lead.reduce((s,x)=>s+x,0)/lead.length).toFixed(1)+" "+L4("j|d|T|ي"):"—","n = "+lead.length]];
