function plNav(n: number){const m=PL.ui.mode;if(!n){PL.ui.date=plToday();PL.ui.mini=null;return}const d=plAnchor();if(PL.ui.view!=="cal"||m==="week"||m==="workweek")PL.ui.date=clAddD(d,7*n);else if(m==="day")PL.ui.date=clAddD(d,n);else if(m==="agenda")PL.ui.date=clAddD(d,14*n);else{const x=new Date(d.slice(0,8)+"01T12:00:00Z");x.setUTCMonth(x.getUTCMonth()+n);PL.ui.date=x.toISOString().slice(0,10)}PL.ui.mini=null}
